verifier_source:
# Exact-integer verifier for the finitary restatement (fragment certificate for L1).
# No imports. No I/O. No filesystem. No network. Deterministic. Exact integer arithmetic only.
# Entry point: verify(witness) -- raises on any failed check (fail closed); returns True on PASS.

WITNESS = {
 "cases": [
  {"case_id": "pos_A_finite", "A": [0,1,2,4,8], "N": 20,
   "f_A_table": {0:0,1:1,2:1,3:1,4:2,5:1,6:2,7:1,8:3,9:1,10:2,11:1,12:1,13:0,14:1,15:1,16:2,17:1,18:1,19:0,20:1},
   "expect": "ACCEPT"},
  {"case_id": "neg_wrong_table", "A": [0,1,2,4,8], "N": 20,
   "f_A_table": {0:0,1:1,2:1,3:1,4:2,5:1,6:2,7:1,8:3,9:1,10:2,11:1,12:1,13:0,14:1,15:1,16:2,17:1,18:1,19:0,20:2},
   "expect": "REJECT"},
  {"case_id": "missing_entry_fails_closed", "A": [0,1,2,4,8], "N": 20,
   "f_A_table": {0:0,1:1,2:1,3:1,4:2,5:1,6:2,7:1,8:3,9:1,10:2,11:1,12:1,13:0,14:1,15:1,16:2,17:1,18:1},
   "expect": "ABORT"},
  {"case_id": "negative_entry_fails_closed", "A": [0,1], "N": 3,
   "f_A_table": {0:0,1:1,2:1,3:-1},
   "expect": "ABORT"},
  {"case_id": "no_table_self_computed", "A": [0,1,3], "N": 12,
   "f_A_table": None, "expect": "ACCEPT"}
 ]
}

def r_A(a_sorted, s, n):
    c = 0
    for a in a_sorted:
        b = n - a
        if b in s:
            c += 1
    return c

def _check_int(v, what):
    if not isinstance(v, int) or isinstance(v, bool):
        raise ValueError("non-integer %s" % what)
    if v < 0:
        raise ValueError("negative %s" % what)
    return v

def verify(witness):
    if not isinstance(witness, dict) or "cases" not in witness:
        raise ValueError("malformed witness")
    for case in witness["cases"]:
        A = case["A"]
        N = case["N"]
        tbl = case["f_A_table"]
        expect = case["expect"]
        if expect not in ("ACCEPT", "REJECT", "ABORT"):
            raise ValueError("bad expect")
        for x in A:
            _check_int(x, "A element")
        _check_int(N, "N")
        a_sorted = sorted(set(A))
        s = set(a_sorted)
        computed = {}
        for n in range(1, N + 1):
            computed[n] = r_A(a_sorted, s, n)
        if tbl is None:
            verdict = "ACCEPT"
        else:
            verdict = "ACCEPT"
            for n in range(1, N + 1):
                if n not in tbl:
                    raise ValueError("missing f_A entry n=%d (fail closed => ABORT)" % n)
                v = _check_int(tbl[n], "f_A[%d]" % n)
                if v != computed[n]:
                    verdict = "REJECT"
                    break
        if expect == "ABORT":
            # An ABORT expectation cannot be reached on a live witness here without an
            # actual raise; a case whose table is complete/correct and expects ABORT is
            # itself a defective witness. To honor ABORT expectations, re-trigger the
            # exact fail-closed condition explicitly and require that it raises.
            trigger = False
            for n in range(1, N + 1):
                if tbl is None or n not in tbl:
                    trigger = True
                    break
                if tbl[n] < 0:
                    trigger = True
                    break
            if not trigger:
                raise ValueError("ABORT expected but fail-closed condition not present in case %s" % case["case_id"])
            # raising here IS the ABORT behavior, demonstrated live:
            if tbl is not None and any(n not in tbl for n in range(1, N + 1)):
                raise ValueError("missing f_A entry n (demonstrated ABORT)" )
            if tbl is not None and any(tbl[n] < 0 for n in range(1, N + 1)):
                raise ValueError("negative f_A entry (demonstrated ABORT)")
            verdict = "ABORT"
        if verdict != expect:
            raise ValueError("case %s: expected %s, verifier produced %s" % (case["case_id"], expect, verdict))
    return True

RESULT = verify(WITNESS)
assert RESULT is True
